// Mini dependency injector: providers registered under tokens, instances cached.
class Injector {
  constructor() { this.recipes = new Map(); this.cache = new Map(); }
  provide(token, factory) { this.recipes.set(token, factory); }
  get(token) {
    if (!this.recipes.has(token)) throw new Error("No provider for " + token.name);
    if (!this.cache.has(token)) {
      // The factory receives the injector, so it can ask for its own dependencies
      this.cache.set(token, this.recipes.get(token)(this));
    }
    return this.cache.get(token); // same instance on every later call
  }
}
