// Injector hierarchy: ask child, then walk up parents; first match wins.
class Injector {
  constructor(name, parent) {
    this.name = name; this.parent = parent || null;
    this.recipes = new Map(); this.cache = new Map();
  }
  provide(token, factory) { this.recipes.set(token, factory); return this; }
  get(token, opts) {
    opts = opts || {};
    if (!opts.skipSelf && this.recipes.has(token)) {
      if (!this.cache.has(token)) this.cache.set(token, this.recipes.get(token)());
      return this.cache.get(token); // instance is cached where it is provided
    }
    if (this.parent && !opts.self) return this.parent.get(token, {});
    if (opts.optional) return null;
    throw new Error("NullInjectorError: no provider for " + token);
  }
}
