// The four provider recipes, resolved by a tiny container.
class Container {
  constructor(providers) { this.p = new Map(providers.map(x => [x.provide, x])); this.cache = new Map(); }
  get(token) {
    const r = this.p.get(token);
    if (!r) throw new Error("no provider for " + String(token));
    if (r.useExisting) return this.get(r.useExisting); // alias: same instance as other token
    if (!this.cache.has(token)) {
      let v;
      if ("useValue" in r) v = r.useValue;               // ready-made value
      else if (r.useClass) v = new r.useClass();         // construct a class
      else v = r.useFactory(this);                       // run a function
      this.cache.set(token, v);                          // recipe runs once per container
    }
    return this.cache.get(token);
  }
}
