// Why inject() only works synchronously: a "current injector" pointer set during construction.
let current = null;
function runInInjectionContext(injector, fn) {
  const prev = current;
  current = injector;          // pointer is set only while fn runs
  try { return fn(); } finally { current = prev; }
}
