// Concurrent 401s share ONE in-flight refresh promise.
let refreshCalls = 0, validToken = "old";
const server = async (token) => (token === "new" ? 200 : 401);
let refresh$ = null;
function refresh() {
  if (!refresh$) {                       // reuse the in-flight refresh if there is one
    refresh$ = new Promise((resolve) => setTimeout(() => {
      refreshCalls++; validToken = "new"; resolve("new");
    }, 10)).finally(() => { refresh$ = null; });
  }
  return refresh$;
}
async function request(name) {
  let status = await server(validToken);
  if (status === 401) {
    const token = await refresh();       // all failed calls wait on the same promise
    status = await server(token);        // retry once with the new token
  }
  console.log(name + " -> " + status);
  return status;
}
(async () => {
  console.log("three calls start with an expired token");
  await Promise.all([request("A"), request("B"), request("C")]);
  console.log("refresh calls:", refreshCalls);
})();
